const quote = (context.selection || '').trim();
if (!quote) { api.showResult('Select the text you want to save first.'); return; }
const source = new URL(context.url);
if (!['https:', 'http:'].includes(source.protocol)) return;
const title = (context.title || source.hostname).replace(/[
]/g, ' ').slice(0, 100);
api.notes.create({ title: 'Quote: ' + title, body: quote.split('
').map(line => '> ' + line).join('
') + '

Source: <' + source.href.replace(/>/g, '%3E') + '>
Page: ' + title + '
Saved: ' + new Date().toISOString().slice(0, 10) });
